    colors=set(v for row in grid for v in row if v!=bg)
    for color in colors:
        for r,row in enumerate(grid):
            xs=[c for c,v in enumerate(row) if v==color]
            if len(xs)>=3:
                for c in range(min(xs),max(xs)+1):
                    if grid[r][c]!=color: out[r][c]=2
        for c in range(w):
            ys=[r for r in range(h) if grid[r][c]==color]
            if len(ys)>=3:
                for r in range(min(ys),max(ys)+1):
                    if grid[r][c]!=color: out[r][c]=2
